        if len(v) % 2:
            raise ValueError("Invalid points")
        return list(zip(v[::2], v[1::2]))
    if name == "rect":
        x = number(element.get("x", "0"))
        y = number(element.get("y", "0"))
        w = number(element.get("width", "0"))
        h = number(element.get("height", "0"))
